  "overview": {
    "text": "Massachusetts is a state in the Northeast’s New England division, with Boston as its capital and an Atlantic coast that includes Cape Cod. Its official name is the Commonwealth of Massachusetts; it ratified the U.S. Constitution on February 6, 1788, becoming the sixth state to join the Union. Long before English colonization, Indigenous communities including the Massachusett, Wampanoag, Nipmuc, and others lived across the region, and Indigenous peoples remain part of Massachusetts today. Plymouth and Boston became early colonial centers, and events in Massachusetts—including protests against British rule—helped shape the movement toward American independence.",
    "source_urls": [
      "https://www.census.gov/programs-surveys/economic-census/geographies/levels/2022-levels.html",
      "https://www.sec.state.ma.us/divisions/cis/download/Mass_Facts.pdf",
      "https://www.sec.state.ma.us/divisions/cis/historical/historical-sketch.htm"
    ]
  },
  "key_facts": [
    {
      "text": "Boston is the state capital; the Secretary of the Commonwealth’s 2023 factsheet dates the city to 1630.",
      "source_urls": [
        "https://www.sec.state.ma.us/divisions/cis/download/Mass_Facts.pdf"
      ]
    },
    {
      "text": "Massachusetts ratified the U.S. Constitution on February 6, 1788, as the sixth of the original 13 states.",
      "source_urls": [
        "https://www.sec.state.ma.us/divisions/cis/download/Mass_Facts.pdf"
      ]
    },
    {
      "text": "The state factsheet lists “Bay State” and “Old Bay State” among the nicknames commonly used for Massachusetts.",
      "source_urls": [
        "https://www.sec.state.ma.us/divisions/cis/download/Mass_Facts.pdf"
      ]
    },
    {
      "text": "The Secretary of the Commonwealth’s historical sketch names Massachusett, Wampanoag, Pennacook, Mahican, Pocumtuck, and Nipmuc communities, and notes that Indigenous communities persist today.",
      "source_urls": [
        "https://www.sec.state.ma.us/divisions/cis/historical/historical-sketch.htm"
      ]
    },
    {
      "text": "The historical sketch describes the Boston Massacre and Boston Tea Party as events in Massachusetts amid rising conflict with Britain before the Revolutionary War.",
      "source_urls": [
        "https://www.sec.state.ma.us/divisions/cis/historical/historical-sketch.htm"
      ]
    }
  ],
